const allDishes=[...breakfasts,...mains];
const proteinLabels={fish:'рыба',chicken:'курица',turkey:'индейка',legumes:'бобовые',tofu:'тофу',egg:'яйца',yogurt:'йогурт',cottage:'творог'};
const sideLabels={oats:'овсянка',bread:'цельнозерновой хлеб',fruit:'фрукты',bulgur:'булгур',buckwheat:'гречка',couscous:'кускус',rice:'бурый рис',pasta:'паста',potato:'картофель',quinoa:'киноа',barley:'перловка'};
const dishById=id=>allDishes.find(d=>d.id===id)||allDishes.find(d=>d.n===id);
const state={people:[],plan:[],checked:{},meta:{},saved:[]};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const clone=x=>JSON.parse(JSON.stringify(x));
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2000)}
function defaultHeight(age,sex){if(age<13)return 140;if(age<18)return sex==='m'?172:163;return sex==='m'?178:165}
function addPerson(data={name:'Алекс',age:32,sex:'f',weight:65,height:165}){const node=$('#personTemplate').content.firstElementChild.cloneNode(true);node.querySelector('.person-name').value=data.name||'';node.querySelector('.person-age').value=data.age||32;node.querySelector('.person-sex').value=data.sex||'f';node.querySelector('.person-weight').value=data.weight||65;node.querySelector('.person-height').value=data.height||defaultHeight(data.age||32,data.sex||'f');node.querySelector('.person-avatar').textContent=(data.name||'А')[0].toUpperCase();node.querySelector('.person-name').addEventListener('input',e=>node.querySelector('.person-avatar').textContent=(e.target.value||'А')[0].toUpperCase());node.querySelector('.remove-person').onclick=()=>{if($$('.person-card').length===1)return showToast('Нужен хотя бы один человек');node.remove()};$('#peopleList').append(node)}
function readPeople(){return $$('.person-card').map(c=>({name:c.querySelector('.person-name').value.trim()||'Без имени',age:+c.querySelector('.person-age').value,sex:c.querySelector('.person-sex').value,weight:+c.querySelector('.person-weight').value,height:+c.querySelector('.person-height').value})).filter(p=>p.age>=3&&p.age<=100&&p.weight>=12&&p.height>=80)}
function calcEER(p){const a=p.age,h=p.height,w=p.weight,level=$('#activity').value;let e;if(a>=19){const t=p.sex==='m'?{sedentary:[753.07,-10.83,6.50,14.10],low:[581.47,-10.83,8.30,14.94],active:[1004.82,-10.83,6.52,15.91]}:{sedentary:[584.90,-7.01,5.72,11.71],low:[575.77,-7.01,6.60,12.14],active:[710.25,-7.01,6.54,12.34]};const c=t[level];e=c[0]+c[1]*a+c[2]*h+c[3]*w}else{const t=p.sex==='m'?{sedentary:[-447.51,3.68,13.01,13.15],low:[19.12,3.68,8.62,20.28],active:[-388.19,3.68,12.66,20.46]}:{sedentary:[55.59,-22.25,8.43,17.07],low:[-297.54,-22.25,12.77,14.73],active:[-189.55,-22.25,11.74,18.34]};const c=t[level];e=c[0]+c[1]*a+c[2]*h+c[3]*w}return Math.round(Math.max(900,Math.min(4500,e)))}
function portion(p){return Math.max(.5,Math.min(1.8,calcEER(p)/2200))}
function totalPortions(){return state.people.reduce((s,p)=>s+portion(p),0)}
function mondayISO(){const d=new Date();const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.toISOString().slice(0,10)}
function dateLabel(iso){if(!iso)return'';return new Date(iso+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}
function weekEnd(iso){const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+6);return d.toISOString().slice(0,10)}
function eligibleMains(){return mains.filter(d=>!$('#vegetarian').checked||d.veg)}
function sequence(pool,count,offset=0){const rotated=pool.map((_,i)=>pool[(i+offset)%pool.length]);return Array.from({length:count},(_,i)=>rotated[i%rotated.length])}
function autoMeals(){const style=$('#cookStyle').value,offset=style==='fast'?2:style==='fresh'?1:0;const bp=sequence(breakfasts,7,offset),mp=sequence(eligibleMains(),14,offset);return days.map((day,i)=>({day,meals:[bp[i],mp[i*2],mp[i*2+1]]}))}
function renderManualBuilder(refill=false){const defaults=autoMeals();const old={};if(!refill)$$('#manualGrid select').forEach(s=>old[s.dataset.key]=s.value);const options=(list,selected)=>list.map(d=>`<option value="${d.id}" ${d.id===selected?'selected':''}>${d.n}</option>`).join('');$('#manualGrid').innerHTML=days.map((day,i)=>`<div class="manual-day"><strong>${day}</strong><label><span>Завтрак</span><select data-key="${i}-0">${options(breakfasts,old[`${i}-0`]||defaults[i].meals[0].id)}</select></label><label><span>Обед</span><select data-key="${i}-1">${options(eligibleMains(),old[`${i}-1`]||defaults[i].meals[1].id)}</select></label><label><span>Ужин</span><select data-key="${i}-2">${options(eligibleMains(),old[`${i}-2`]||defaults[i].meals[2].id)}</select></label></div>`).join('')}
function manualMeals(){return days.map((day,i)=>({day,meals:[0,1,2].map(j=>dishById($(`[data-key="${i}-${j}"]`).value))}))}
function generatePlan(){state.people=readPeople();if(!state.people.length)return showToast('Проверьте возраст, рост и вес');if($('#planMode').value==='manual'&&!$('#manualGrid').children.length)renderManualBuilder(true);state.plan=$('#planMode').value==='manual'?manualMeals():autoMeals();state.checked={};state.meta={weekStart:$('#weekStart').value||mondayISO(),createdAt:new Date().toISOString(),mode:$('#planMode').value};saveCurrent();renderPlan();$('#results').classList.remove('hidden');$('#shoppingView').classList.add('hidden');setView('menu');$('#results').scrollIntoView({behavior:'smooth'})}
function scaledIngredients(m){const f=totalPortions();return m.i.map(([n,q,u])=>`${n} — ${formatQty(q*f,u,false)}`)}
function renderPlan(){const total=totalPortions(),style=$('#cookStyle').value,avg=Math.round(state.people.reduce((s,p)=>s+calcEER(p),0)/state.people.length);$('#summaryPeople').textContent=state.people.length;$('#summaryTime').textContent=Math.round(state.plan.flatMap(d=>d.meals).reduce((s,m)=>s+m.t,0)/21);$('#summaryPrep').textContent=style==='fresh'?2:style==='fast'?4:3;$('#summaryEnergy').textContent=avg.toLocaleString('ru-RU');$('#planDates').textContent=`Неделя ${dateLabel(state.meta.weekStart)} — ${dateLabel(weekEnd(state.meta.weekStart))} · создано ${new Date(state.meta.createdAt).toLocaleDateString('ru-RU')}`;$('#batchPlan').innerHTML='<strong>Заготовка на 60 минут</strong><span>Сварите 2–3 крупы, запеките белок на 2–3 дня, вымойте овощи и смешайте базовую заправку. Точные шаги есть внутри каждой карточки.</span>';$('#weekGrid').innerHTML=state.plan.map((d,di)=>`<article class="day-card"><header class="day-head"><strong>${d.day}</strong><span>${Math.round(total*10)/10} порц.</span></header>${d.meals.map((m,mi)=>`<div class="meal"><div class="meal-photo"><img src="${m.img}" alt="${m.n}" loading="lazy"></div><div class="meal-type"><span>${['Завтрак','Обед','Ужин'][mi]}</span><button aria-label="Заменить блюдо" onclick="swapMeal(${di},${mi})">↻</button></div><h3>${m.n}</h3><p>${m.d}</p><div class="component-tags"><span>${proteinLabels[m.proteinKey]||'белок'}</span><span>${sideLabels[m.sideKey]||'гарнир'}</span></div><div class="meal-meta"><span>◷ ${m.t} мин</span>${m.b?'<span>заготовка</span>':''}</div>${mi?'<div class="plate-dots"><i></i><i></i><i></i></div>':''}<details class="recipe"><summary>Как приготовить</summary><div class="recipe-body"><strong>Ингредиенты на семью</strong><ul>${scaledIngredients(m).map(x=>`<li>${x}</li>`).join('')}</ul><strong>Шаги</strong><ol>${m.steps.map(x=>`<li>${x}</li>`).join('')}</ol></div></details></div>`).join('')}</article>`).join('');renderShopping();renderSavedPlans()}
window.swapMeal=(di,mi)=>{const pool=mi===0?breakfasts:eligibleMains(),old=state.plan[di].meals[mi],idx=pool.findIndex(d=>d.id===old.id);state.plan[di].meals[mi]=pool[(idx+1+pool.length)%pool.length];saveCurrent();renderPlan();showToast('Блюдо заменено')};
function aggregate(){const out={},factor=totalPortions();state.plan.flatMap(d=>d.meals).forEach(m=>m.i.forEach(([name,q,u,c])=>{const key=name+'|'+u;if(!out[key])out[key]={name,q:0,u,c};out[key].q+=q*factor}));return Object.values(out).map(x=>({...x,q:x.u==='шт'?Math.ceil(x.q):Math.ceil(x.q/50)*50})).sort((a,b)=>a.name.localeCompare(b.name,'ru'))}
function peopleWord(n){return n%10===1&&n%100!==11?'человек':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'человека':'человек'}
function renderShopping(){const items=aggregate();$('#shopCount').textContent=items.length;$('#shoppingSubtitle').textContent=`${dateLabel(state.meta.weekStart)} · ${state.people.length} ${peopleWord(state.people.length)}`;$('#shoppingGrid').innerHTML=Object.entries(categories).map(([key,title])=>{const list=items.filter(x=>x.c===key);if(!list.length)return'';return `<section class="shop-category"><h3>${title}</h3>${list.map(x=>{const id=x.name+'|'+x.u;return `<label class="shop-item"><input type="checkbox" data-id="${id}" ${state.checked[id]?'checked':''}><span>${x.name}</span><b>${formatQty(x.q,x.u)}</b></label>`}).join('')}</section>`}).join('');$$('.shop-item input').forEach(el=>el.onchange=()=>{state.checked[el.dataset.id]=el.checked;saveCurrent();updateProgress()});updateProgress()}
function formatQty(q,u,round=true){if(round&&u==='шт')q=Math.ceil(q);else if(round)q=Math.ceil(q/50)*50;else q=u==='шт'?Math.ceil(q):Math.round(q);if(u==='г'&&q>=1000)return (Math.round(q/100)/10).toString().replace('.',',')+' кг';return `${q} ${u}`}
function updateProgress(){const all=$$('.shop-item input'),done=all.filter(x=>x.checked).length;$('#progressText').textContent=`${done} из ${all.length}`;$('#shopProgress').style.width=(all.length?done/all.length*100:0)+'%'}
function setView(view){$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='shopping'){if(!state.plan.length)return showToast('Сначала составьте меню');$('.hero').classList.add('hidden');$('#planner').classList.add('hidden');$('#results').classList.add('hidden');$('#shoppingView').classList.remove('hidden');renderShopping();scrollTo({top:0,behavior:'smooth'})}else{$('.hero').classList.remove('hidden');$('#planner').classList.remove('hidden');$('#shoppingView').classList.add('hidden');if(state.plan.length)$('#results').classList.remove('hidden')}}
function copyList(){const items=aggregate(),text=Object.entries(categories).map(([k,t])=>{const a=items.filter(x=>x.c===k);return a.length?`${t}\n${a.map(x=>'☐ '+x.name+' — '+formatQty(x.q,x.u)).join('\n')}`:''}).filter(Boolean).join('\n\n');navigator.clipboard.writeText(text).then(()=>showToast('Список скопирован'))}
function snapshot(){return {people:clone(state.people),plan:state.plan.map(d=>({day:d.day,mealIds:d.meals.map(m=>m.id)})),checked:clone(state.checked),meta:clone(state.meta),activity:$('#activity').value,cookStyle:$('#cookStyle').value,vegetarian:$('#vegetarian').checked,planMode:state.meta.mode||$('#planMode').value}}
function inflate(raw){state.people=(raw.people||[]).map(p=>({...p,height:p.height||defaultHeight(p.age,p.sex)}));state.plan=(raw.plan||[]).map(d=>({day:d.day,meals:(d.mealIds||d.meals||[]).map(x=>dishById(typeof x==='string'?x:(x.id||x.n))).filter(Boolean)}));state.checked=raw.checked||{};state.meta=raw.meta||{weekStart:mondayISO(),createdAt:new Date().toISOString(),mode:'auto'};$('#activity').value=['0.9','1','1.12'].includes(String(raw.activity))?({0.9:'sedentary',1:'low',1.12:'active'}[raw.activity]):(raw.activity||'low');$('#cookStyle').value=raw.cookStyle||'mixed';$('#vegetarian').checked=!!raw.vegetarian;$('#planMode').value=raw.planMode||state.meta.mode||'auto';$('#weekStart').value=state.meta.weekStart||mondayISO();$('#peopleList').innerHTML='';(state.people.length?state.people:[{name:'Алекс',age:32,sex:'f',weight:65,height:165}]).forEach(addPerson);toggleManual();if(state.plan.length){renderPlan();$('#results').classList.remove('hidden')}}
function saveCurrent(){localStorage.setItem('tarelka-current-v2',JSON.stringify(snapshot()))}
function loadSaved(){try{return JSON.parse(localStorage.getItem('tarelka-saved-v2'))||[]}catch{return[]}}
function persistSaved(){localStorage.setItem('tarelka-saved-v2',JSON.stringify(state.saved.slice(0,12)))}
function saveNamedPlan(){if(!state.plan.length)return showToast('Сначала составьте меню');const snap=snapshot(),existing=state.saved.findIndex(x=>x.meta.weekStart===snap.meta.weekStart);snap.id=existing>=0?state.saved[existing].id:String(Date.now());snap.savedAt=new Date().toISOString();if(existing>=0)state.saved.splice(existing,1);state.saved.unshift(snap);persistSaved();renderSavedPlans();showToast('Неделя сохранена на устройстве')}
function renderSavedPlans(){if(!state.saved.length){$('#savedPlans').innerHTML='<span class="empty-save">Пока нет сохранённых планов</span>';return}$('#savedPlans').innerHTML=state.saved.map(p=>`<article class="saved-card"><button class="load-plan" data-load="${p.id}"><strong>${dateLabel(p.meta.weekStart)}</strong><span>${p.people.length} ${peopleWord(p.people.length)} · ${p.meta.mode==='manual'?'ручной':'авто'}</span></button><button class="delete-plan" data-delete="${p.id}" aria-label="Удалить">×</button></article>`).join('');$$('[data-load]').forEach(b=>b.onclick=()=>{const p=state.saved.find(x=>x.id===b.dataset.load);if(p){inflate(clone(p));saveCurrent();showToast('Сохранённая неделя открыта')}});$$('[data-delete]').forEach(b=>b.onclick=()=>{state.saved=state.saved.filter(x=>x.id!==b.dataset.delete);persistSaved();renderSavedPlans()})}
function toggleManual(){const on=$('#planMode').value==='manual';$('#manualBuilder').classList.toggle('hidden',!on);if(on)renderManualBuilder();$('#generateBtn span:first-child').textContent=on?'Применить выбранные блюда':'Составить меню на неделю'}
function loadInitial(){state.saved=loadSaved();renderSavedPlans();let raw;try{raw=JSON.parse(localStorage.getItem('tarelka-current-v2'))}catch{}if(!raw){try{raw=JSON.parse(localStorage.getItem('tarelka-plan'))}catch{}}if(raw)inflate(raw);else{addPerson();$('#weekStart').value=mondayISO()}}
$('#addPersonBtn').onclick=()=>addPerson({name:'',age:30,sex:'f',weight:65,height:165});$('#generateBtn').onclick=generatePlan;$('#openShopping').onclick=()=>setView('shopping');$('#savePlanBtn').onclick=saveNamedPlan;$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#copyList').onclick=copyList;$('#printList').onclick=()=>window.print();$('#resetBtn').onclick=()=>{localStorage.removeItem('tarelka-current-v2');location.reload()};$('#planMode').onchange=toggleManual;$('#vegetarian').onchange=()=>{if($('#planMode').value==='manual')renderManualBuilder(true)};$('#fillManual').onclick=()=>renderManualBuilder(true);
loadInitial();
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
